var e=`nasiko deploy ./my-agent`;function t(t){return[`nasiko connect ${t}`,`nasiko new openai my-agent`,e]}var n=new Intl.RelativeTimeFormat(`en`,{numeric:`auto`});function r(e,t=Date.now()){if(!e)return`—`;let r=Date.parse(e);if(Number.isNaN(r))return`—`;let i=Math.round((r-t)/1e3),a=Math.abs(i);return a<60?n.format(i,`second`):a<3600?n.format(Math.round(i/60),`minute`):a<86400?n.format(Math.round(i/3600),`hour`):n.format(Math.round(i/86400),`day`)}export{t as n,r,e as t};